`<!DOCTYPE html>
<html lang="si">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title> Tech තක්ෂිලාව - මුල් පිටුව</title>
  <style>
    body {
      font-family: "Noto Sans Sinhala", Arial, sans-serif;
      margin: 0;
      background: #f0f4f8;
      color: #222;
    }
    header {
      background-color: #004080;
      color: white;
      padding: 15px 0;
      text-align: center;
      position: relative;
    }
    header img.logo {
      height: 60px;
      display: block;
      margin: 0 auto;
      cursor: pointer;
    }
    header h1 {
      margin: 8px 0 0 0;
      font-size: 2.2rem;
      font-weight: 700;
    }
    nav {
      position: absolute;
      top: 20px;
      right: 30px;
    }
    nav a.login-btn {
      background-color: #ff6600;
      color: white;
      padding: 8px 18px;
      border-radius: 5px;
      text-decoration: none;
      font-weight: 600;
      transition: background-color 0.3s ease;
      font-size: 1rem;
    }
    nav a.login-btn:hover {
      background-color: #e65c00;
    }
    main {
      max-width: 1100px;
      margin: 30px auto;
      padding: 0 20px 50px;
    }
    .cards {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 20px;
    }
    .card {
      background: white;
      border-radius: 12px;
      box-shadow: 0 4px 10px rgba(0,0,0,0.1);
      padding: 20px;
      text-align: center;
      cursor: pointer;
      transition: transform 0.25s ease, box-shadow 0.25s ease;
    }
    .card:hover {
      transform: translateY(-8px);
      box-shadow: 0 10px 20px rgba(0,0,0,0.15);
    }
    .card img {
      width: 90px;
      height: 90px;
      margin-bottom: 15px;
      object-fit: contain;
    }
    .card h3 {
      margin-bottom: 8px;
      color: #004080;
      font-size: 1.3rem;
      font-weight: 700;
    }
    .card p {
      font-size: 1rem;
      color: #555;
    }
    footer {
      background: #222;
      color: #eee;
      text-align: center;
      padding: 20px 10px;
      font-size: 1.1rem;
    }
    .social-icons {
      margin-top: 12px;
    }
    .social-icons a {
      margin: 0 14px;
      color: #eee;
      font-size: 1.7rem;
      text-decoration: none;
      transition: color 0.3s ease;
    }
    .social-icons a:hover {
      color: #1da1f2;
    }
  </style>
</head>
<body>

<header>
  <!-- මෙතන ඔබගේ ලෝගෝ එක දැමිය හැක -->
  <img src="https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Sri_Lanka_Emblem.svg/120px-Sri_Lanka_Emblem.svg.png" alt="SFT පාසල ලෝගෝ" class="logo" />
  <h1> Tech තක්ෂිලාව</h1>

  <nav>
    <a href="login.html" class="login-btn">ලොගින් වන්න</a>
  </nav>
</header>

<main>
  <section id="video-slider-section" style="max-width: 900px; margin: 40px auto; padding: 0 10px;">
  <h2 style="text-align:center; color:#004080; font-family:'Noto Sans Sinhala', Arial, sans-serif; font-weight:700; margin-bottom:15px;">
    වීඩියෝ ටියුන්අප්
  </h2>
  <div id="video-slider" style="overflow-x:auto; white-space: nowrap; scroll-behavior: smooth; border-radius: 12px; box-shadow: 0 3px 8px rgba(0,0,0,0.15); padding:10px; background:#fff;">
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
    <video class="slider-video" width="320" height="180" controls style="display:inline-block; margin-right:12px; border-radius:8px;">
      <source src="videos/logo.mp4" type="video/mp4" />
      Your browser does not support the video tag.
    </video>
  </div>
</section>

<script>
  const slider = document.getElementById('video-slider');
  const slideWidth = 332; // video width (320) + margin-right (12)
  let scrollPosition = 0;
  const maxScrollLeft = slider.scrollWidth - slider.clientWidth;

  function autoSlide() {
    scrollPosition += slideWidth;
    if(scrollPosition > maxScrollLeft){
      scrollPosition = 0;
    }
    slider.scrollTo({
      left: scrollPosition,
      behavior: 'smooth'
    });
  }

  // auto slide every 3.5 seconds
  setInterval(autoSlide, 3500);
</script>

  <div class="cards">
    <div class="card" onclick="location.href='sft-technology.html'">
      <img src="https://img.icons8.com/ios-filled/100/000000/robot-2.png" alt="SFT Technology" />
      <h3>SFT තාක්ෂණවේදය</h3>
      <p>විද්‍යාව හා තාක්ෂණයේ නව නව දැනුම</p>
    </div>

    <div class="card" onclick="location.href='et-engineering.html'">
      <img src="https://img.icons8.com/ios-filled/100/000000/engineering.png" alt="ET Engineering" />
      <h3>ET ඉංජිනේරු තාක්ෂණවේදය</h3>
      <p>ඉංජිනේරු ක්ෂේත්‍රයේ මූලික දැනුම</p>
    </div>

    <div class="card" onclick="location.href='bsd-biosystem.html'">
      <img src="https://img.icons8.com/ios-filled/100/000000/dna.png" alt="BSD Biosystem Technology" />
      <h3>BSD Biosystem Technology</h3>
      <p>ජීව විද්‍යාව හා පද්ධති</p>
    </div>

    <div class="card" onclick="location.href='ict-automation.html'">
      <img src="https://img.icons8.com/ios-filled/100/000000/computer.png" alt="ICT Automation" />
      <h3>ICT Automation Communication</h3>
      <p>තොරතුරු හා සන්නිවේදන තාක්ෂණය</p>
    </div>

    <div class="card" onclick="location.href='agriculture.html'">
      <img src="https://img.icons8.com/ios-filled/100/000000/tractor.png" alt="Agriculture" />
      <h3>කෘෂි විද්‍යාව</h3>
      <p>කෘෂිකාර්මික අධ්‍යාපනය</p>
    </div>

    <div class="card" onclick="location.href='geography.html'">
      <img src="https://img.icons8.com/ios-filled/100/000000/globe.png" alt="Geography" />
      <h3>ජෝග්‍රොපි (භූගෝල විද්‍යාව)</h3>
      <p>පෘථිවිය හා පරිසර විද්‍යාව</p>
    </div>


</main>

<footer>
  <div>අප හා සම්බන්ධ වන්න</div>
  <div class="social-icons">
    <a href="https://facebook.com/yourpage" target="_blank" title="Facebook">📘</a>
    <a href="https://instagram.com/yourpage" target="_blank" title="Instagram">📸</a>
    <a href="https://youtube.com/yourchannel" target="_blank" title="YouTube">▶️</a>
    <a href="https://wa.me/yourphonenumber" target="_blank" title="WhatsApp">💬</a>
  </div>
</footer>

</body>
</html>
`
